(* @case global *)
(* @test
version: 1
input: source
runs:
  - name: cpu
    pipeline: sum-i32-cpu
    arguments:
      - name: a
        dtype: i32
        shape: [6]
        values: [1, 2, 3, 4, 5, 6]
  - name: metal
    pipeline: sum-i32-metal
    arguments:
      - name: a
        dtype: i32
        shape: [6]
        values: [1, 2, 3, 4, 5, 6]
*)
(* @assert:cpu:result
[21]
*)
(* @assert:cpu:shape
[]
*)
(* @assert:metal:result
[21]
*)
(* @assert:metal:shape
[]
*)
sum(a)

(* @case rows *)
(* @test
version: 1
input: source
runs:
  - name: cpu
    pipeline: sum-i32-cpu
    arguments:
      - name: a
        dtype: i32
        shape: [2, 3]
        values: [1, 2, 3, 4, 5, 6]
  - name: metal
    pipeline: sum-i32-metal
    arguments:
      - name: a
        dtype: i32
        shape: [2, 3]
        values: [1, 2, 3, 4, 5, 6]
*)
(* @assert:cpu:result
[6, 15]
*)
(* @assert:cpu:shape
[2]
*)
(* @assert:metal:result
[6, 15]
*)
(* @assert:metal:shape
[2]
*)
sum(a, axis=1)

